package com.nextaicommerce.platform.catalog;
import java.net.URI;import java.util.*;
import org.junit.jupiter.api.Test;import org.springframework.mock.web.*;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.web.server.ResponseStatusException;import org.springframework.test.util.ReflectionTestUtils;
import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class CatalogPictureControllerTest {
 private static UsernamePasswordAuthenticationToken auth(String role){return new UsernamePasswordAuthenticationToken("editor@example.invalid","unused",List.of(new SimpleGrantedAuthority("ROLE_"+role)));}
 @Test void accountCandidatesAlwaysUseSelectedAccountAndNeverEnableLocalSync(){var service=mock(CatalogPictureService.class);var c=new CatalogPictureController(service);var s=new MockHttpSession();UUID t=UUID.randomUUID(),item=UUID.randomUUID();s.setAttribute("selectedTenantId",t);when(service.candidates(t,"editor@example.invalid",item,false)).thenReturn(List.of());var response=c.accountCandidates(item,s,auth("OPERATOR"));assertThat(response.getHeaders().getCacheControl()).contains("no-store");assertThat(((Map<?,?>)response.getBody()).get("canSync")).isEqualTo(false);verify(service).candidates(t,"editor@example.invalid",item,false);verify(service,never()).canSync(any(),any(),any());}
 @Test void accountRolesCannotReadOrWriteGlobalImages(){var service=mock(CatalogPictureService.class);var c=new CatalogPictureController(service);for(String role:List.of("OWNER","ADMIN","OPERATOR","VIEWER")){assertThatThrownBy(()->c.globalCandidates(UUID.randomUUID(),new MockHttpSession(),auth(role))).isInstanceOf(ResponseStatusException.class);assertThatThrownBy(()->c.globalChoose(UUID.randomUUID(),UUID.randomUUID(),true,new MockHttpSession(),auth(role))).isInstanceOf(ResponseStatusException.class);}verifyNoInteractions(service);}
 @Test void sharedWriteRequiresConfirmationBeforeResolvingOrDownloading(){var service=mock(CatalogPictureService.class);var c=new CatalogPictureController(service);assertThatThrownBy(()->c.globalChoose(UUID.randomUUID(),UUID.randomUUID(),false,new MockHttpSession(),auth("PLATFORM_ADMIN"))).isInstanceOf(ResponseStatusException.class);verifyNoInteractions(service);}
 @Test void invalidUploadNeverWritesAndValidGlobalUploadIsExplicit()throws Exception{var service=mock(CatalogPictureService.class);var c=new CatalogPictureController(service);UUID item=UUID.randomUUID(),tenant=UUID.randomUUID();var s=new MockHttpSession();s.setAttribute("selectedTenantId",tenant);assertThat(c.globalUpload(item,new MockMultipartFile("image","x.svg","image/svg+xml",new byte[]{1}),true,s,auth("PLATFORM_ADMIN")).getStatusCode().value()).isEqualTo(400);verifyNoInteractions(service);var out=new java.io.ByteArrayOutputStream();try{javax.imageio.ImageIO.write(new java.awt.image.BufferedImage(1,1,1),"png",out);byte[] bytes=out.toByteArray();assertThat(c.globalUpload(item,new MockMultipartFile("image","x.png","image/png",bytes),true,s,auth("PLATFORM_ADMIN")).getStatusCode().value()).isEqualTo(200);verify(service).save(tenant,"editor@example.invalid",item,true,null,"image/png",bytes);}catch(Exception e){throw new AssertionError(e);}}
 @Test void publicCandidateHostsCannotBecomeAnArbitraryDownloadOrPrivateUpload(){for(String url:List.of("https://m.media-amazon.com/images/I/1.jpg","https://images-na.ssl-images-amazon.com/images/I/1.jpg"))assertThat(CatalogPictureService.publicAmazonImage(url)).isTrue();for(String url:List.of("http://m.media-amazon.com/1.jpg","https://localhost/x","/app/catalog/products/private/image","https://user@m.media-amazon.com/x","https://m.media-amazon.com:444/x","https://m.media-amazon.com.evil.test/x"))assertThat(CatalogPictureService.publicAmazonImage(url)).isFalse();}
}
